alter table public.bolge_verileri add column if not exists merkez_nufus int, add column if not exists koy_nufus int, add column if not exists dogum int, add column if not exists olum int, add column if not exists evlenme int, add column if not exists bosanma int, add column if not exists yabanci_satis_12ay int, add column if not exists yabanci_satis_onceki12 int, add column if not exists yabanci_satis_son_ay text;
on conflict (il, ilce, yil) do update set kaynak=excluded.kaynak, nufus=excluded.nufus, nufus_artisi=excluded.nufus_artisi, merkez_nufus=excluded.merkez_nufus, koy_nufus=excluded.koy_nufus, dogum=excluded.dogum, olum=excluded.olum, evlenme=excluded.evlenme, bosanma=excluded.bosanma, yabanci_satis_12ay=excluded.yabanci_satis_12ay, yabanci_satis_onceki12=excluded.yabanci_satis_onceki12, yabanci_satis_son_ay=excluded.yabanci_satis_son_ay, guncelleme=now();
